signature.advancedArgs:
{
  "type": "object",
  "properties": {
    "showTab": {
      "type": "string",
      "description": "Set when the user asks to see the dates on one tab of the Manual In and Out screen - e.g. 'what are the dates in the pending tab'. Pass the tab name as the user says it: Regularize, Pending, Valid Swipes or Off Shifts. No date is needed (the team and admin tools still need the employee). Returns only that tab's dates and submits nothing - show the dates as returned."
    },
    "date": {
      "type": "string",
      "description": "Date the manual In and Out is being added for. Use the format returned by the dateFormat tool (MM/DD/YYYY for en-US, otherwise DD/MM/YYYY). Ask the user for this if not provided. Leave it out only when the user just wants to see their records for a date range (pass fromDate/toDate) or the roster list (showRosters). Also call with the date when the user asks for the status of a pending request on that date - for a Pending day the tool returns the status, what was requested (old -> new In/Out and break times), the comment and who it is waiting for (pendingRequest); show that as returned."
    },
    "inDate": {
      "type": "string",
      "description": "In date, in the format returned by the dateFormat tool. Give it with inTime when the user is giving the In. The screen submits an In on its own, an Out on its own, or both, so one side is enough - ask the user which they want to give and never insist on the other. Offer suggested.inDate as the default; never assume it."
    },
    "inTime": {
      "type": "string",
      "description": "In time in HH:mm 24-hour format, e.g. 08:30. Give it with inDate when the user is giving the In; leave both out for an Out-only entry. Offer suggested.inTime as the default."
    },
    "outDate": {
      "type": "string",
      "description": "Out date, in the format returned by the dateFormat tool. Give it with outTime when the user is giving the Out; leave both out for an In-only entry. An Out Date on the day AFTER the In Date is normal for shifts past midnight (shiftDetails.canEndNextDay) - never question it. Offer suggested.outDate as the default."
    },
    "outTime": {
      "type": "string",
      "description": "Out time in HH:mm 24-hour format, e.g. 17:30. Give it with outDate when the user is giving the Out. Check it against outDate, not against inTime. Offer suggested.outTime as the default."
    },
    "reason": {
      "type": "string",
      "description": "Reason/comment explaining why the manual In and Out is being added. Required before the record is submitted."
    },
    "otherEntries": {
      "type": "array",
      "description": "When the user asks for several days in one request, pass on every call the OTHER days of that request that are not submitted yet, each with the values the user gave. The screen submits such days together and refuses all of them when two overlap across midnight, so the tool checks the overlap in each day's preview. Preview every day first; submit none until all previews passed.",
      "items": {
        "type": "object",
        "properties": {
          "date": {
            "type": "string",
            "description": "That day, in the dateFormat format."
          },
          "inDate": {
            "type": "string"
          },
          "inTime": {
            "type": "string",
            "description": "HH:mm"
          },
          "outDate": {
            "type": "string"
          },
          "outTime": {
            "type": "string",
            "description": "HH:mm"
          }
        }
      }
    },
    "confirmed": {
      "type": "boolean",
      "description": "Set to true, together with previewToken, only after the user has reviewed the preview and explicitly confirmed. Set to false (or omit) to just preview/validate without submitting anything. Never send it on the first call - the tool validates and returns the preview first."
    },
    "previewToken": {
      "type": "string",
      "description": "The previewToken from the preview the user confirmed. Required with confirmed:true. Without it, or if any value changed since that preview, nothing is submitted and the preview is returned again - show it and ask for confirmation."
    },
    "breaks": {
      "type": "array",
      "description": "Optional breaks - none, one or as many as the user wants. After showing the shift details, tell the user they can add breaks, but do not insist. Each break needs both times, must end after it starts, must sit within the In and Out date-times and the shift's allowed period, and must not overlap another break of the day (shiftDetails.recordedBreaks lists the ones already recorded). A break after midnight is fine on a shift whose period reaches there.",
      "items": {
        "type": "object",
        "properties": {
          "breakInTime": {
            "type": "string",
            "description": "Break start time in HH:mm 24-hour format, e.g. 12:00."
          },
          "breakOutTime": {
            "type": "string",
            "description": "Break end time in HH:mm 24-hour format, e.g. 13:00."
          },
          "breakNo": {
            "type": "integer",
            "description": "Only to CHANGE a recorded break: its breakNo from shiftDetails.recordedBreaks. Leave it out to add a new break."
          }
        },
        "required": [
          "breakInTime",
          "breakOutTime"
        ]
      }
    },
    "breakInTime": {
      "type": "string",
      "description": "Single-break shorthand: break start time in HH:mm. Prefer the breaks list. If given, breakOutTime must be given too."
    },
    "breakOutTime": {
      "type": "string",
      "description": "Single-break shorthand: break end time in HH:mm. Prefer the breaks list. If given, breakInTime must be given too."
    },
    "dateSelectMode": {
      "enum": [
        "last7days",
        "last30days",
        "period"
      ],
      "description": "Search Criteria date selection mode, matching the page radio buttons: last7days (Last 7 Days), last30days (Last 30 Days), period (By Period, uses fromDate/toDate). Defaults to period with a wide range."
    },
    "fromDate": {
      "type": "string",
      "description": "Search range start date in the format returned by the dateFormat tool. Only used when dateSelectMode is period. Pass it (with toDate) when the user asks to see their manual In and Out records for a date range. If omitted, a wide default range is used. When date is given it must fall inside the range."
    },
    "toDate": {
      "type": "string",
      "description": "Search range end date in the format returned by the dateFormat tool. Only used when dateSelectMode is period. Pass it (with fromDate) when the user asks to see their manual In and Out records for a date range. If omitted, a wide default range is used. When date is given it must fall inside the range."
    },
    "isGroupByEmployee": {
      "type": "boolean",
      "description": "Optional Group By Employee checkbox on the Search Criteria panel. Omit it to use the screen's own default."
    },
    "showRosters": {
      "type": "boolean",
      "description": "Set to true when the user asks to see the roster details. Returns every roster group with its rosters (or only the group named in rosterGroup) and submits nothing. No date is needed."
    },
    "rosterGroup": {
      "type": "string",
      "description": "Optional roster group, by id or name, exactly as listed by showRosters. Omit it to use the screen's first roster group. Do not ask the user for it unless they want a specific roster."
    },
    "rosterCode": {
      "type": "string",
      "description": "Optional roster code, as listed by showRosters. Takes precedence over rosterName. Omit it to use the first roster of the roster group, as the screen does."
    },
    "rosterName": {
      "type": "string",
      "description": "Optional roster name, as listed by showRosters. Resolved to a roster code within the roster group. Ignored when rosterCode is given."
    }
  },
  "required": []
}
